hl.config({
    xwayland = {
        force_zero_scaling = true,
    },
})

hl.on("hyprland.start", function()
    hl.exec_cmd("dbus-update-activation-environment PATH WAYLAND_DISPLAY XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE")
    hl.exec_cmd("killall -q xdg-desktop-portal-hyprland xdg-desktop-portal")
    hl.exec_cmd("bash -c \"/usr/lib/xdg-desktop-portal-hyprland || /usr/libexec/xdg-desktop-portal-hyprland\"")
    hl.exec_cmd("bash -c \"sleep 2 && (/usr/lib/xdg-desktop-portal || /usr/libexec/xdg-desktop-portal)\"")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("hyprpolkitagent")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("start-navbar")
    hl.exec_cmd("hyprsunset")
    hl.exec_cmd("swaync")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("bash ~/.config/hypr/scripts/wallpapers/check-video.sh")
    hl.exec_cmd("hypr-nice")
    hl.exec_cmd("sleep 1 &&  swww-daemon && swww restore &")
end)

